BEGIN;
CREATE TABLE public.legal_document_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  kind text NOT NULL CHECK (kind IN ('terms', 'privacy')),
  version text NOT NULL,
  content jsonb NOT NULL,
  published_at timestamptz NOT NULL DEFAULT now(),
  is_current boolean NOT NULL DEFAULT false,
  UNIQUE(kind, version)
);
CREATE UNIQUE INDEX legal_document_current_kind ON public.legal_document_versions(kind) WHERE is_current;
CREATE TABLE public.legal_acceptances (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES public.users(id) ON DELETE CASCADE,
  document_version_id uuid NOT NULL REFERENCES public.legal_document_versions(id),
  accepted_at timestamptz NOT NULL DEFAULT now(),
  ip_address inet,
  user_agent text,
  source text NOT NULL CHECK (source IN ('registration', 'google_registration', 'renewal')),
  UNIQUE(user_id, document_version_id)
);
ALTER TABLE public.legal_document_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.legal_acceptances ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.protect_legal_document_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id OR NEW.kind IS DISTINCT FROM OLD.kind
    OR NEW.version IS DISTINCT FROM OLD.version OR NEW.content IS DISTINCT FROM OLD.content
    OR NEW.published_at IS DISTINCT FROM OLD.published_at THEN
    RAISE EXCEPTION 'Published legal document versions are immutable; insert a new version';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER legal_document_version_immutable BEFORE UPDATE ON public.legal_document_versions
FOR EACH ROW EXECUTE FUNCTION public.protect_legal_document_version();
INSERT INTO public.legal_document_versions(kind, version, content, published_at, is_current) VALUES ('terms', '1.0', '{"en":[[{"kind":"h2","text":"Agreement to Our Legal Terms"},{"kind":"p","text":"We are CERTRACE (‘we’, ‘us’, or ‘our’). We operate the website https://certrace.co (the ‘Site’), as well as any other related products and services that refer or link to these legal terms (the ‘Legal Terms’) (collectively, the ‘Services’)."},{"kind":"p","text":"You can contact us by email at contact@certrace.co or by mail to wasawat@certrace.co, Thailand."},{"kind":"p","text":"These Legal Terms constitute a legally binding agreement made between you, whether personally or on behalf of an entity (‘User’ or ‘you’), and CERTRACE, concerning your access to and use of the Services. You agree that by accessing the Services, you have read, understood, and agreed to be bound by all of these Legal Terms. IF YOU DO NOT AGREE WITH ALL OF THESE LEGAL TERMS, THEN YOU ARE EXPRESSLY PROHIBITED FROM USING THE SERVICES AND YOU MUST DISCONTINUE USE IMMEDIATELY."},{"kind":"p","text":"Supplemental terms and conditions or documents that may be posted on the Services from time to time are hereby expressly incorporated herein by reference. We reserve the right, in our sole discretion, to make changes or modifications to these Legal Terms at any time and for any reason."},{"kind":"p","text":"The Services are intended for users who are at least 20 years old. Persons under the age of 20 are not permitted to use or register for the Services."}],[{"kind":"h2","text":"1. Our Services"},{"kind":"p","text":"The User agrees to register and create a user account on the Site in accordance with the methods and procedures prescribed by the Company, in order to use the Site under the conditions set out in this Agreement. The User also agrees not to engage in any act that violates any applicable law, rule, or regulation, or public order or good morals, whether domestic or international, or that violates the conditions set out in this Agreement, whether those are in force now or come into force in the future, through this website."}],[{"kind":"h2","text":"2. Intellectual Property Rights"},{"kind":"p","text":"Our intellectual property. We are the owner or the licensee of all intellectual property rights in our Services, including all source code, databases, functionality, software, website designs, audio, video, text, photographs, and graphics in the Services (collectively, the ‘Content’), as well as the trademarks, service marks, and logos contained therein (the ‘Marks’)."},{"kind":"p","text":"Our Content and Marks are protected by copyright and trademark laws (and various other intellectual property rights and unfair competition laws) and treaties around the world. The Content and Marks are provided in or through the Services ‘AS IS’ for your internal business purpose only."},{"kind":"p","text":"Your use of our Services. Subject to your compliance with these Legal Terms, including the ‘Prohibited Activities’ section below, we grant you a non-exclusive, non-transferable, revocable license to:"},{"kind":"li","text":"access the Services; and"},{"kind":"li","text":"download or print a copy of any portion of the Content to which you have properly gained access."},{"kind":"p","text":"The User owns its own input data and outputs, and may use reports externally for regulatory filings and buyer disclosure. Except as set out in this section or elsewhere in our Legal Terms, no part of the Services and no Content or Marks may be copied, reproduced, aggregated, republished, uploaded, posted, publicly displayed, encoded, translated, transmitted, distributed, sold, licensed, or otherwise exploited for any commercial purpose whatsoever, without our express prior written permission."},{"kind":"p","text":"If you wish to make any use of the Services, Content, or Marks other than as set out in this section or elsewhere in our Legal Terms, please address your request to: contact@certrace.co. If we ever grant you the permission to post, reproduce, or publicly display any part of our Services or Content, you must identify us as the owners or licensors of the Services, Content, or Marks and ensure that any copyright or proprietary notice appears or is visible on posting, reproducing, or displaying our Content."},{"kind":"p","text":"We reserve all rights not expressly granted to you in and to the Services, Content, and Marks. Any breach of these Intellectual Property Rights will constitute a material breach of our Legal Terms and your right to use our Services will terminate immediately."},{"kind":"p","text":"Your submissions. Please review this section and the ‘Prohibited Activities’ section carefully prior to using our Services to understand the (a) rights you give us and (b) obligations you have when you post or upload any content through the Services."},{"kind":"p","text":"Submissions: By directly sending us any question, comment, suggestion, idea, feedback, or other information about the Services (‘Submissions’), you agree to assign to us all intellectual property rights in such Submission. You agree that we shall own this Submission and be entitled to its unrestricted use and dissemination for any lawful purpose, commercial or otherwise, without acknowledgment or compensation to you."},{"kind":"p","text":"You are responsible for what you post or upload: By sending us Submissions through any part of the Services you:"},{"kind":"li","text":"confirm that you have read and agree with our ‘Prohibited Activities’ and will not post, send, publish, upload, or transmit through the Services any Submission that is illegal, harassing, hateful, harmful, defamatory, obscene, bullying, abusive, discriminatory, threatening to any person or group, sexually explicit, false, inaccurate, deceitful, or misleading; and"},{"kind":"li","text":"warrant that any such Submission is original to you or that you have the necessary rights and licences to submit such Submissions and that you have full authority to grant us the above-mentioned rights in relation to your Submissions."},{"kind":"p","text":"You are solely responsible for your Submissions and you expressly agree to reimburse us for any and all losses that we may suffer because of your breach of (a) this section, (b) any third party’s intellectual property rights, or (c) applicable law."}],[{"kind":"h2","text":"3. User Representations"},{"kind":"p","text":"By using the Services, you represent and warrant that: (1) all registration information you submit will be true, accurate, current, and complete; (2) you will maintain the accuracy of such information and promptly update such registration information as necessary; (3) you have the legal capacity and you agree to comply with these Legal Terms; (4) you are not a minor in the jurisdiction in which you reside; (5) you will not access the Services through automated or non-human means, whether through a bot, script or otherwise; (6) you will not use the Services for any illegal or unauthorised purpose; and (7) your use of the Services will not violate any applicable law or regulation."},{"kind":"p","text":"If you provide any information that is untrue, inaccurate, not current, or incomplete, we have the right to suspend or terminate your account and refuse any and all current or future use of the Services (or any portion thereof)."}],[{"kind":"h2","text":"4. User Registration"},{"kind":"p","text":"You may be required to register to use the Services. You agree to keep your password confidential and will be responsible for all use of your account and password. We reserve the right to remove, reclaim, or change a username you select if we determine, in our sole discretion, that such username is inappropriate, obscene, or otherwise objectionable."}],[{"kind":"h2","text":"5. Purchases and Payment"},{"kind":"p","text":"We accept the following forms of payment:"},{"kind":"li","text":"Visa"},{"kind":"li","text":"Mastercard"},{"kind":"li","text":"PayPal"},{"kind":"p","text":"You agree to provide current, complete, and accurate purchase and account information for all purchases made via the Services. You further agree to promptly update account and payment information, including email address, payment method, and payment card expiration date, so that we can complete your transactions and contact you as needed. Sales tax will be added to the price of purchases as required by us. We may change prices at any time. All payments shall be in Thai baht (THB)."},{"kind":"p","text":"You agree to pay all charges at the prices then in effect for your purchases and any applicable shipping fees, and you authorise us to charge your chosen payment provider for any such amounts upon placing your order. We reserve the right to correct any errors or mistakes in pricing, even if we have already requested or received payment."},{"kind":"p","text":"We reserve the right, in our sole discretion, to refuse, suspend, or cancel the provision of the Services, or any order or subscription placed through the Services, at any time and without liability to you. This includes, without limitation, the right to limit or cancel purchases per person, per household, or per order; orders placed by or under the same User account, the same payment method, or the same billing; and orders that, in our sole judgement, are inappropriate."}],[{"kind":"h2","text":"6. Subscriptions"},{"kind":"p","text":"Billing and Renewal. Subscriptions will not be renewed automatically. We will contact you by email prior to expiry to ask if you wish to renew your subscription and to communicate the cost of renewing your subscription."},{"kind":"p","text":"Free Trial. We offer a 30-day free trial to new users who register with the Services. The account will not be charged, and the subscription will be suspended at the end of the free trial until it is upgraded to a paid version."},{"kind":"p","text":"Cancellation. You can cancel your subscription at any time by logging into your account. Your cancellation will take effect at the end of the current paid term. If you have any questions or are unsatisfied with our Services, please email us at contact@certrace.co."},{"kind":"p","text":"Fee Changes. We may, from time to time, make changes to the subscription fee and will communicate any price changes to you in accordance with applicable law."}],[{"kind":"h2","text":"7. Prohibited Activities"},{"kind":"p","text":"Users may not access or use the Services for any purpose other than that for which we make the Services available. The Services may not be used in connection with any commercial endeavours, except that the User has the right to use outputs for the User’s business purposes and for those purposes specifically endorsed or approved by us."},{"kind":"p","text":"As a User of the Services, you agree not to:"},{"kind":"li","text":"Systematically retrieve data or other content from the Services to create or compile, directly or indirectly, a collection, compilation, database, or directory without written permission from us."},{"kind":"li","text":"Trick, defraud, or mislead us and other users, especially in any attempt to learn sensitive account information such as user passwords."},{"kind":"li","text":"Circumvent, disable, or otherwise interfere with security-related features of the Services, including features that prevent or restrict the use or copying of any Content or enforce limitations on the use of the Services and/or the Content contained therein."},{"kind":"li","text":"Use any information obtained from the Services in order to harass, abuse, or harm another person."},{"kind":"li","text":"Make improper use of our support services or submit false reports of abuse or misconduct."},{"kind":"li","text":"Use the Services in a manner inconsistent with any applicable laws or regulations."},{"kind":"li","text":"Engage in unauthorised framing of or linking to the Services."},{"kind":"li","text":"Upload or transmit (or attempt to upload or to transmit) viruses, Trojan horses, or other material, including excessive use of capital letters and spamming (continuous posting of repetitive text), that interferes with any party’s uninterrupted use and enjoyment of the Services or modifies, impairs, disrupts, alters, or interferes with the use, features, functions, operation, or maintenance of the Services."},{"kind":"li","text":"Engage in any automated use of the system, such as using scripts to send comments or messages, or using any data mining, robots, or similar data gathering and extraction tools."},{"kind":"li","text":"Delete the copyright or other proprietary rights notice from any Content."},{"kind":"li","text":"Attempt to impersonate another user or person or use the username of another user."},{"kind":"li","text":"Upload or transmit (or attempt to upload or to transmit) any material that acts as a passive or active information collection or transmission mechanism, including without limitation, clear graphics interchange formats (‘gifs’), 1×1 pixels, web bugs, cookies, or other similar devices (sometimes referred to as ‘spyware’ or ‘passive collection mechanisms’ or ‘pcms’)."},{"kind":"li","text":"Interfere with, disrupt, or create an undue burden on the Services or the networks or services connected to the Services."},{"kind":"li","text":"Harass, annoy, intimidate, or threaten any of our employees or agents engaged in providing any portion of the Services to you."},{"kind":"li","text":"Attempt to bypass any measures of the Services designed to prevent or restrict access to the Services, or any portion of the Services."},{"kind":"li","text":"Copy or adapt the Services’ software, including but not limited to Flash, PHP, HTML, JavaScript, or other code."},{"kind":"li","text":"Except as permitted by applicable law, decipher, decompile, disassemble, or reverse engineer any of the software comprising or in any way making up a part of the Services."},{"kind":"li","text":"Except as may be the result of